export const getSearchDocsUrl = (params: SearchDocsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/docs/search?${stringifiedParams}` : `/api/v1/docs/search`
}

/**
 * Known limitation (S14b), not closed by this contract. Every snippet is masked, but the search matches against the stored text of the docs, so whether a query finds a doc tells a reader something about a value that was hidden. How the docs index treats a flagged value (for example by matching on the masked text) is for owner 14. The MCP search tools sit on the same port.
 * @summary Search docs
 */
export const searchDocs = async (params: SearchDocsParams, options?: Parameters<typeof apiFetch>[1]): Promise<DocHits> => {

  return apiFetch<DocHits>(getSearchDocsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





